<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{studentAPI}from'../../api/student';import type{ApiKey,Model,ModelCategory,Organization,Project,RequestedModel}from'../../api/types';import{APIError}from'../../api/client';import StatusProgress from'../../components/StatusProgress.vue';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import{useToast}from'../../composables/useToast'
const orgs=ref<Organization[]>([]),projects=ref<Project[]>([]),models=ref<Model[]>([]),keys=ref<ApiKey[]>([]),detail=ref<ApiKey|null>(null),secret=ref(''),copied=ref(false),claimConfirm=ref<ApiKey|null>(null),modelDialog=ref(false),modelStage=ref<'id'|'details'|'existing'>('id'),resolved=ref<Model|null>(null),error=ref(''),loading=ref(false),toast=useToast()
const form=reactive({organization_id:'',project_id:'',model_ids:[] as string[],requested_models:[] as RequestedModel[],name:''});const custom=reactive<RequestedModel>({model_id:'',display_name:'',description:null,category:'text',capabilities:[],input_modalities:[],output_modalities:[],context_window:null,max_output_tokens:null});const capability=ref('')
const allCount=computed(()=>form.model_ids.length+form.requested_models.length);const canSubmit=computed(()=>form.organization_id&&form.project_id&&form.name.trim()&&allCount.value>0&&allCount.value<=100)
async function load(preserve=true){loading.value=true;try{const [o,m,k]=await Promise.all([studentAPI.organizations(),studentAPI.models(),studentAPI.keys()]);orgs.value=o;models.value=m;keys.value=k;if(!preserve)detail.value=k[0]??null}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function chooseOrg(){if((form.model_ids.length||form.requested_models.length)&&!confirm('切换组织将清空项目、已选模型和新模型草稿，是否继续？'))return;form.project_id='';form.model_ids=[];form.requested_models=[];projects.value=form.organization_id?await studentAPI.projects(form.organization_id):[]}
function toggleModel(model:Model){const key=model.model_id.toLowerCase(),i=form.model_ids.findIndex(v=>v.toLowerCase()===key);if(i>=0)form.model_ids.splice(i,1);else if(allCount.value<100)form.model_ids.push(model.model_id)}
function resetCustom(){Object.assign(custom,{model_id:'',display_name:'',description:null,category:'text',capabilities:[],input_modalities:[],output_modalities:[],context_window:null,max_output_tokens:null});capability.value='';modelStage.value='id';resolved.value=null}
async function resolveModel(){error.value='';try{const result=await studentAPI.resolveModel(custom.model_id);if(result.exists&&result.model){resolved.value=result.model;modelStage.value='existing'}else modelStage.value='details'}catch(e){error.value=msg(e)}}
function addCapability(){const value=capability.value.trim();if(value&&!custom.capabilities.some(v=>v.toLowerCase()===value.toLowerCase()))custom.capabilities.push(value);capability.value=''}
function acceptModel(){if(resolved.value){toggleModel(resolved.value);toast.success('已采用平台权威模型配置')}else{if(!custom.display_name.trim()||!custom.capabilities.length||!custom.input_modalities.length||!custom.output_modalities.length){error.value='请完整填写模型卡片字段';return}const key=custom.model_id.toLowerCase();form.model_ids=form.model_ids.filter(v=>v.toLowerCase()!==key);form.requested_models=form.requested_models.filter(v=>v.model_id.toLowerCase()!==key);form.requested_models.push(JSON.parse(JSON.stringify(custom)))}modelDialog.value=false;resetCustom()}
async function submit(){if(!canSubmit.value)return;error.value='';try{const created=await studentAPI.submit({...form});Object.assign(form,{organization_id:'',project_id:'',model_ids:[],requested_models:[],name:''});projects.value=[];await load();detail.value=created;toast.success('密钥申请已提交')}catch(e){error.value=msg(e)}}
async function show(id:string){try{detail.value=await studentAPI.key(id);secret.value='';copied.value=false}catch(e){error.value=msg(e)}}async function claim(){if(!claimConfirm.value)return;try{const result=await studentAPI.claim(claimConfirm.value.id);secret.value=result.api_key;detail.value=claimConfirm.value;claimConfirm.value=null;await load();toast.success('密钥已领取并激活')}catch(e){error.value=msg(e)}}async function copy(){try{await navigator.clipboard.writeText(secret.value);copied.value=true;toast.success('已复制密钥')}catch{const element=document.querySelector<HTMLElement>('.secret');const selection=getSelection();if(element&&selection){const range=document.createRange();range.selectNodeContents(element);selection.removeAllRanges();selection.addRange(range)}toast.error('复制失败，已选中文本，请手动复制')}}function closeSecret(){if(secret.value&&!copied.value&&!confirm('密钥尚未复制，关闭后无法再次查看。确定关闭？'))return;secret.value='';copied.value=false;detail.value=null}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败，请稍后重试'}function refresh(){void load()}onMounted(()=>{void load(false);window.addEventListener('nebula:refresh',refresh)});onBeforeUnmount(()=>window.removeEventListener('nebula:refresh',refresh))
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">STUDENT</p><h1>申请密钥</h1><p class="muted">按组织、项目、模型与 Key 名称完成申请。</p></div><button class="button secondary" @click="load()">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><div class="grid two"><section class="panel"><h2>新申请</h2><form @submit.prevent="submit"><label>1. 组织<select v-model="form.organization_id" @change="chooseOrg"><option value="">请选择组织</option><option v-for="org in orgs" :key="org.id" :value="org.id">{{org.name}}</option></select></label><label>2. 项目<select v-model="form.project_id" :disabled="!form.organization_id"><option value="">请选择项目</option><option v-for="project in projects" :key="project.id" :value="project.id" :disabled="project.status!=='active'||!project.has_mentor">{{project.name}}{{project.status!=='active'?'（已停用）':!project.has_mentor?'（暂无负责导师）':''}}</option></select></label><fieldset :disabled="!form.project_id"><legend>3. 模型白名单（{{allCount}}/100）</legend><input placeholder="搜索可见模型"/><div v-for="model in models" :key="model.id" class="list-row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}}{{model.status==='inactive'?' · 需老师重新配置后才能终审':''}}</p></div><button type="button" class="button" :class="form.model_ids.some(v=>v.toLowerCase()===model.model_id.toLowerCase())?'secondary':'ghost'" @click="toggleModel(model)">{{form.model_ids.some(v=>v.toLowerCase()===model.model_id.toLowerCase())?'已选择':'选择'}}</button></div><div class="chip-list"><span v-for="model in form.requested_models" :key="model.model_id" class="chip">{{model.display_name}} · 新模型 <button type="button" class="icon-button" @click="form.requested_models=form.requested_models.filter(v=>v!==model)">×</button></span></div><button type="button" class="button secondary" @click="modelDialog=true;resetCustom()">申请新模型</button></fieldset><label>4. Key 名称<input v-model="form.name" maxlength="128" placeholder="例如 research-key"/></label><button class="button primary wide" :disabled="!canSubmit||loading">提交申请</button></form></section><section class="panel"><div class="panel-heading"><h2>我的申请</h2><span>{{keys.length}}</span></div><article v-for="key in keys" :key="key.id" class="key-card"><div class="row"><div><strong>{{key.name}}</strong><p class="muted">{{key.organization.name}} · {{key.project.name}} · {{key.models.length}} 个模型</p></div><StatusBadge :status="key.status"/></div><StatusProgress :current="key.progress.current" :completed="key.progress.completed_steps"/><div class="actions"><button class="button ghost" @click="show(key.id)">审核状态</button><button v-if="key.status==='approved'" class="button primary" @click="claimConfirm=key">一次性领取</button></div></article></section></div><AppDialog :open="modelDialog" title="申请新模型" @update:open="modelDialog=$event"><form @submit.prevent="modelStage==='id'?resolveModel():acceptModel"><label>模型 ID<input v-model="custom.model_id" :readonly="modelStage!=='id'" maxlength="256" required/></label><template v-if="modelStage==='details'"><label>显示名称<input v-model="custom.display_name" maxlength="256" required/></label><label>描述<textarea v-model="custom.description" maxlength="2048" rows="3"/></label><label>类别<select v-model="custom.category"><option v-for="v in ['text','image','audio','video','multimodal','embedding','rerank']" :key="v">{{v}}</option></select></label><label>能力<div class="row"><input v-model="capability" @keydown.enter.prevent="addCapability"/><button type="button" class="button secondary" @click="addCapability">添加</button></div></label><div class="chip-list"><span v-for="v in custom.capabilities" :key="v" class="chip">{{v}}</span></div><fieldset><legend>输入模态</legend><label v-for="v in ['text','image','audio','video']" :key="v"><input v-model="custom.input_modalities" type="checkbox" :value="v"/>{{v}}</label></fieldset><fieldset><legend>输出模态</legend><label v-for="v in ['text','image','audio','video']" :key="v"><input v-model="custom.output_modalities" type="checkbox" :value="v"/>{{v}}</label></fieldset><label>上下文长度<input v-model.number="custom.context_window" type="number" min="1"/></label><label>最大输出 Token<input v-model.number="custom.max_output_tokens" type="number" min="1"/></label></template><div v-if="modelStage==='existing'&&resolved" class="panel"><strong>{{resolved.display_name}}</strong><p class="muted">{{resolved.model_id}} · 平台已有模型，将采用平台权威配置。</p><StatusBadge :status="resolved.status"/></div><div class="actions"><button class="button primary">{{modelStage==='id'?'检查模型':'加入白名单'}}</button></div></form></AppDialog><AppDialog :open="Boolean(claimConfirm)" title="确认一次性领取" @update:open="claimConfirm=$event?claimConfirm:null"><p>完整 API Key 仅显示一次。领取后立即转为 ACTIVE。</p><div class="actions"><button class="button primary" @click="claim">确认领取</button></div></AppDialog><AppDialog :open="Boolean(detail)" :title="secret?'立即保存 API Key':'申请详情'" @update:open="secret?closeSecret():detail=null"><template v-if="secret"><p class="secret">{{secret}}</p><button class="button secondary" @click="copy">{{copied?'已复制':'复制密钥'}}</button></template><template v-else-if="detail"><StatusProgress :current="detail.progress.current" :completed="detail.progress.completed_steps"/><p>{{detail.organization.name}} · {{detail.project.name}}</p><p>{{detail.models.map(m=>m.model_id).join('、')}}</p><div v-for="audit in detail.audits" :key="audit.created_at" class="list-row"><span>{{audit.actor_role}} · {{audit.action}}</span><span>{{audit.comment||'无意见'}}</span></div></template></AppDialog></section></template>
